 "content": "def transform(grid):
    # The marked shape is copied wherever its silhouette occurs in the background:
    # mark the cells that are zero at matching offsets from each original marker.
    h, w = len(grid), len(grid[0])
    color = next((v for row in grid for v in row if v not in (0, 1)), None)
    if color is None:
        return [r[:] for r in grid]
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
    out = [row[:] for row in grid]
    # Match all translations of the marked shape, using non-colored cells as wildcard,
    # but only color zero positions when the whole shape overlays zero/marker cells.
    for dr in range(-h, h):
        for dc in range(-w, w):
            if dr == 0 and dc == 0:
                continue
            q = [(r+dr,c+dc) for r,c in pts]
            if all(0 <= r < h and 0 <= c < w for r,c in q) and all(grid[r][c] != 1 for r,c in q):
                for r,c in q:
                    if grid[r][c] == 0: out[r][c] = color
    return out

